def solution(heights):
    if not heights: return []
    m, n = len(heights), len(heights[0])
    pac, atl = set(), set()
    def dfs(r, c, ocean):
        ocean.add((r, c))
        for nr, nc in [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]:
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in ocean:
                if heights[nr][nc] >= heights[r][c]:
                    dfs(nr, nc, ocean)
    for c in range(n):
        dfs(0, c, pac)
        dfs(m - 1, c, atl)
    for r in range(m):
        dfs(r, 0, pac)
        dfs(r, n - 1, atl)
    return [list(cell) for cell in (pac & atl)]
